import { Route, Routes } from 'react-router-dom'
import Home from './pages/Home'
import SaibaMais from './pages/SaibaMais'

const Rotas = () => {
  return (
    <Routes>
      {/* Rota principal (Home) */}
      <Route path="/" element={<Home />} />

      {/* Rota Saiba Mais */}
      <Route path="/saibamais" element={<SaibaMais />} />
    </Routes>
  )
}

export default Rotas
